tool_input.command:
cat > migrations/002_product_discount.sql <<'EOF'
alter table products
  add column discount_percent integer not null default 0
  check (discount_percent between 0 and 100);
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('"select id, name, price_cents, stock from products order by id"','"select id, name, price_cents, stock, discount_percent from products order by id"')
s=s.replace('''  app.get("/orders"''','''  app.patch("/products/:id", async (req, res) => {
    if (res.locals.user.role !== "admin") return sendError(res, 403, "forbidden", "Admin only");
    const id = Number(req.params.id);
    const discount = req.body?.discountPercent;
    if (!Number.isInteger(discount) || discount < 0 || discount > 100) {
      return sendError(res, 400, "invalid_discount", "discountPercent must be a whole number from 0 to 100");
    }
    const { rows } = Number.isInteger(id)
      ? await pool.query(
          "update products set discount_percent = $1 where id = $2 returning id, name, price_cents, stock, discount_percent",
          [discount, id],
        )
      : { rows: [] };
    if (rows.length === 0) return sendError(res, 404, "not_found", "Product not found");
    res.json(rows[0]);
  });

  app.get("/orders"''',1)
open(p,'w').write(s)
EOF
pnpm typecheck 2>&1 | tail -5; pnpm test 2>&1 | tail -12
